import sys

def is_in_set(n, a, b):
    # Check if n can be expressed as a combination of a and b starting from 1
    if n == 1:
        return True
    if n < 1:
        return False

    # Use a set to keep track of visited numbers to avoid infinite loops
    visited = set()
    queue = [1]

    while queue:
        current = queue.pop(0)

        if current == n:
            return True

        if current * a not in visited:
            visited.add(current * a)
            queue.append(current * a)

        if current + b not in visited:
            visited.add(current + b)
            queue.append(current + b)

    return False

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    t = int(data[0])
    index = 1
    results = []

    for _ in range(t):
        n = int(data[index])
        a = int(data[index + 1])
        b = int(data[index + 2])
        index += 3

        if is_in_set(n, a, b):
            results.append("Yes")
        else:
            results.append("No")

    print("\n".join(results))

if __name__ == "__main__":
    main()
